service.method:

UPDATE SUSMT SET
	   PW_RESET_DATE = ${PW_RESET_REQ_DATE}
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND UPPER(USER_ID) = UPPER(${USER_ID})


UPDATE SUSMT SET 
	   PW_RESET_REQ_DATE = '',
	   PW_RESET_REQ_TIME = '',
	   PASSWORD = ${ENCRYPTED_PASSWORD},
	   CHANGE_USER_ID = ${USER_ID},
	   CHANGE_DATE = ${current.DATE},
	   CHANGE_TIME = ${current.TIME},
	   PW_RESET_DATE = ${current.DATE}
	   , PASS_CHECK_CNT = '0'
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND UPPER(USER_ID) = UPPER(${USER_ID})
   AND PW_RESET_REQ_DATE = ${PW_RESET_REQ_DATE}
   AND PW_RESET_REQ_TIME = ${PW_RESET_REQ_TIME}


UPDATE SUSMT 
   SET  PASSWORD  = ${PASSWORD}
       ,PW_RESET_FLAG = 'N'
       ,PW_RESET_DATE = ${current.DATE} 
       ,PASS_CHECK_CNT = 0
 WHERE #DB_OWNER#NVL(DEL_FLAG, 'N' ) = 'N'
   AND HOUSE_CODE = ${HOUSE_CODE}
   AND UPPER(USER_ID)  = UPPER(${USER_ID})


SELECT #DB_OWNER#NVL(MAX(DOC_SEQ), 0 ) AS SEQ
    FROM SFILE
    WHERE HOUSE_CODE = ${session.HOUSE_CODE}
        AND DOC_NO = ${LOGO_ATTACH_KEY}
